from functools import wraps
from flask import (
    Blueprint,
    request,
    session,
    jsonify,
    redirect,
    url_for,
)
from werkzeug.security import check_password_hash, generate_password_hash


auth_bp = Blueprint("auth", __name__)

# In-memory admin store (replace with database table in production)
# Default admin: username=admin, password=admin123
_ADMIN_STORE = {
    "admin": generate_password_hash("admin123"),
}


def admin_required(f):
    """Decorator to require admin login."""
    @wraps(f)
    def decorated(*args, **kwargs):
        if "admin_id" not in session:
            if request.is_json:
                return jsonify({"error": "Login required"}), 401
            return redirect(url_for("dashboard.login_page"))
        return f(*args, **kwargs)
    return decorated


@auth_bp.route("/login", methods=["POST"])
def login():
    """Admin login endpoint."""
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")

    if not username or not password:
        return jsonify({"error": "Username and password required"}), 400

    stored_hash = _ADMIN_STORE.get(username)
    if stored_hash is None or not check_password_hash(stored_hash, password):
        return jsonify({"error": "Invalid credentials"}), 401

    session.permanent = True
    session["admin_id"] = username
    session["admin_username"] = username
    return jsonify({"message": "Login successful", "username": username})


@auth_bp.route("/logout", methods=["POST"])
def logout():
    """Admin logout endpoint."""
    session.clear()
    return jsonify({"message": "Logout successful"})


@auth_bp.route("/status", methods=["GET"])
def status():
    """Check authentication status."""
    if "admin_id" in session:
        return jsonify({
            "authenticated": True,
            "username": session.get("admin_username"),
        })
    return jsonify({"authenticated": False}), 401
"}

