from flask import Blueprint, request, jsonify
from sqlalchemy.exc import IntegrityError
from models import db, User, Card, FaceTemplate
from services.pin_service import hash_pin
from services.rfid_service import hash_uid
from services.face_service import enrol_face
from auth import admin_required


users_bp = Blueprint("users", __name__)


@users_bp.route("", methods=["GET"])
@admin_required
def list_users():
    """List all users with pagination."""
    page = request.args.get("page", 1, type=int)
    per_page = request.args.get("per_page", 10, type=int)
    per_page = min(per_page, 100)

    query = User.query.order_by(User.created_at.desc())
    pagination = query.paginate(page=page, per_page=per_page, error_out=False)

    return jsonify({
        "users": [u.to_dict() for u in pagination.items],
        "total": pagination.total,
        "pages": pagination.pages,
        "current_page": page,
        "per_page": per_page,
    })


@users_bp.route("/<int:user_id>", methods=["GET"])
@admin_required
def get_user(user_id):
    """Get a single user by ID."""
    user = User.query.get_or_404(user_id)
    data = user.to_dict()
    data["cards"] = [
        {"card_id": c.card_id, "is_active": c.is_active, "created_at": c.created_at.isoformat()}
        for c in user.cards
    ]
    if user.face_template:
        data["face_template"] = {
            "template_id": user.face_template.template_id,
            "created_at": user.face_template.created_at.isoformat(),
        }
    return jsonify(data)


@users_bp.route("", methods=["POST"])
@admin_required
def create_user():
    """Create a new user with PIN and optional card/face."""
    data = request.get_json(silent=True) or {}

    username = data.get("username", "").strip()
    full_name = data.get("full_name", "").strip()
    raw_pin = data.get("pin", "").strip()
    raw_uid = data.get("rfid_uid", "").strip()

    if not username or not full_name or not raw_pin:
        return jsonify({"error": "username, full_name, and pin are required"}), 400

    if not raw_pin.isdigit() or not (4 <= len(raw_pin) <= 6):
        return jsonify({"error": "PIN must be 4-6 digits"}), 400

    pin_hash = hash_pin(raw_pin)
    user = User(username=username, full_name=full_name, pin_hash=pin_hash)

    try:
        db.session.add(user)
        db.session.flush()  # Get user_id without committing

        if raw_uid:
            uid_hash, uid_salt = hash_uid(raw_uid)
            card = Card(
                user_id=user.user_id,
                uid_hash=uid_hash,
                uid_salt=uid_salt,
            )
            db.session.add(card)

        db.session.commit()
        return jsonify({"message": "User created", "user": user.to_dict()}), 201
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "Username or RFID card already exists"}), 409
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@users_bp.route("/<int:user_id>", methods=["PUT"])
@admin_required
def update_user(user_id):
    """Update user details."""
    user = User.query.get_or_404(user_id)
    data = request.get_json(silent=True) or {}

    if "full_name" in data:
        user.full_name = data["full_name"].strip()
    if "is_active" in data:
        user.is_active = bool(data["is_active"])

    try:
        db.session.commit()
        return jsonify({"message": "User updated", "user": user.to_dict()})
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@users_bp.route("/<int:user_id>", methods=["DELETE"])
@admin_required
def delete_user(user_id):
    """Delete a user and all associated data."""
    user = User.query.get_or_404(user_id)
    try:
        db.session.delete(user)
        db.session.commit()
        return jsonify({"message": "User deleted"})
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": str(e)}), 500


@users_bp.route("/<int:user_id>/cards", methods=["POST"])
@admin_required
def add_card(user_id):
    """Register a new RFID card for a user."""
    user = User.query.get_or_404(user_id)
    data = request.get_json(silent=True) or {}
    raw_uid = data.get("rfid_uid", "").strip()

    if not raw_uid:
        return jsonify({"error": "rfid_uid is required"}), 400

    uid_hash, uid_salt = hash_uid(raw_uid)
    card = Card(user_id=user.user_id, uid_hash=uid_hash, uid_salt=uid_salt)

    try:
        db.session.add(card)
        db.session.commit()
        return jsonify({"message": "Card registered", "card_id": card.card_id}), 201
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "RFID card already registered"}), 409


@users_bp.route("/<int:user_id>/face", methods=["POST"])
@admin_required
def enrol_face_endpoint(user_id):
    """Enrol a face template for a user from an uploaded image."""
    user = User.query.get_or_404(user_id)

    if "image" not in request.files:
        return jsonify({"error": "image file is required"}), 400

    image_file = request.files["image"]
    if image_file.filename == "":
        return jsonify({"error": "No file selected"}), 400

    image_bytes = image_file.read()
    if not image_bytes:
        return jsonify({"error": "Empty file"}), 400

    encoding_bytes = enrol_face(image_bytes)
    if encoding_bytes is None:
        return jsonify({
            "error": "Face detection failed. Ensure the image contains a single, clearly visible face."
        }), 422

    # Delete existing template if any
    if user.face_template:
        db.session.delete(user.face_template)

    template = FaceTemplate(user_id=user.user_id, encoding=encoding_bytes)
    db.session.add(template)
    db.session.commit()

    return jsonify({"message": "Face enrolled successfully"})
"}

