const API = {
    async request(url, options = {}) {
        const res = await fetch(url, {
            headers: { 'Content-Type': 'application/json', ...options.headers },
            ...options
        });
        if (res.status === 401) {
            window.location.href = '/login';
            return null;
        }
        return res;
    },
    async json(url, options = {}) {
        const res = await this.request(url, options);
        return res ? res.json() : null;
    }
};

// Navigation
function initNavigation() {
    const links = document.querySelectorAll('#sidebar .nav-link');
    links.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const section = link.dataset.section;
            showSection(section);
            links.forEach(l => l.parentElement.classList.remove('active'));
            link.parentElement.classList.add('active');
        });
    });
}

function showSection(name) {
    document.querySelectorAll('.section').forEach(s => s.classList.add('d-none'));
    const target = document.getElementById(name + '-section');
    if (target) target.classList.remove('d-none');

    if (name === 'overview') loadOverview();
    if (name === 'users') loadUsers();
    if (name === 'cards') loadCards();
    if (name === 'enrol') loadEnrolmentUsers();
    if (name === 'logs') loadLogs();
    if (name === 'evaluation') loadEvaluation();
}

// Logout
document.getElementById('logoutBtn')?.addEventListener('click', async () => {
    await fetch('/auth/logout', { method: 'POST' });
    window.location.href = '/login';
});

// Overview
async function loadOverview() {
    const stats = await API.json('/api/logs/stats');
    if (!stats) return;
    document.getElementById('statTotalAttempts').textContent = stats.total_attempts || 0;
    document.getElementById('statGranted').textContent = stats.granted || 0;
    document.getElementById('statDenied').textContent = stats.denied || 0;
    document.getElementById('statPinFails').textContent = stats.pin_failures || 0;
    document.getElementById('statRfidFails').textContent = stats.rfid_failures || 0;
    document.getElementById('statFaceFails').textContent = stats.face_failures || 0;

    const users = await API.json('/api/users?page=1&per_page=1');
    document.getElementById('statTotalUsers').textContent = users?.total || 0;

    const logs = await API.json('/api/logs?page=1&per_page=10');
    renderLogsTable(logs?.logs || [], 'recentLogsTable');
}

// Users
let currentUsersPage = 1;

async function loadUsers(page = 1) {
    currentUsersPage = page;
    const data = await API.json(`/api/users?page=${page}&per_page=10`);
    if (!data) return;

    const tbody = document.getElementById('usersTable');
    tbody.innerHTML = '';
    data.users.forEach(u => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td>${u.user_id}</td>
            <td>${escapeHtml(u.username)}</td>
            <td>${escapeHtml(u.full_name)}</td>
            <td>${u.is_active ? '<span class="badge bg-success">Active</span>' : '<span class="badge bg-secondary">Inactive</span>'}</td>
            <td>${u.has_face_template ? '<i class="bi bi-check-circle-fill text-success"></i>' : '<i class="bi bi-x-circle-fill text-muted"></i>'}</td>
            <td>${u.card_count}</td>
            <td>${formatDate(u.created_at)}</td>
            <td>
                <button class="btn btn-sm btn-outline-danger" onclick="deleteUser(${u.user_id})">
                    <i class="bi bi-trash"></i>
                </button>
            </td>
        `;
        tbody.appendChild(tr);
    });

    renderPagination(data, 'usersPagination', loadUsers);
}

async function deleteUser(userId) {
    if (!confirm('Delete this user and all associated data?')) return;
    const res = await API.request(`/api/users/${userId}`, { method: 'DELETE' });
    if (res && res.ok) loadUsers(currentUsersPage);
}

// Add User
const addUserModal = document.getElementById('addUserModal');
if (addUserModal) {
    document.getElementById('saveUserBtn').addEventListener('click', async () => {
        const username = document.getElementById('newUsername').value.trim();
        const full_name = document.getElementById('newFullName').value.trim();
        const pin = document.getElementById('newPin').value;
        const rfid_uid = document.getElementById('newRfidUid').value.trim();
        const alert = document.getElementById('addUserAlert');

        const res = await API.request('/api/users', {
            method: 'POST',
            body: JSON.stringify({ username, full_name, pin, rfid_uid })
        });

        const data = await res.json();
        if (res.ok) {
            alert.className = 'alert alert-success';
            alert.textContent = 'User created successfully!';
            alert.classList.remove('d-none');
            document.getElementById('addUserForm').reset();
            setTimeout(() => bootstrap.Modal.getInstance(addUserModal).hide(), 800);
            loadUsers();
        } else {
            alert.className = 'alert alert-danger';
            alert.textContent = data.error || 'Failed to create user';
            alert.classList.remove('d-none');
        }
    });

    addUserModal.addEventListener('hidden.bs.modal', () => {
        document.getElementById('addUserAlert').classList.add('d-none');
        document.getElementById('addUserForm').reset();
    });
}

// Cards
async function loadCards() {
    const users = await API.json('/api/users?page=1&per_page=100');
    const select = document.getElementById('cardUserSelect');
    select.innerHTML = '<option value="">Select user...</option>';
    users?.users.forEach(u => {
        const opt = document.createElement('option');
        opt.value = u.user_id;
        opt.textContent = `${u.username} (${u.full_name})`;
        select.appendChild(opt);
    });

    const tbody = document.getElementById('cardsTable');
    tbody.innerHTML = '';
    users?.users.forEach(u => {
        u.cards?.forEach?.(c => {
            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td>${escapeHtml(u.username)}</td>
                <td><code>${c.uid_hash.substring(0, 16)}...</code></td>
                <td>${c.is_active ? '<span class="badge bg-success">Active</span>' : '<span class="badge bg-secondary">Inactive</span>'}</td>
            `;
            tbody.appendChild(tr);
        });
    });
}

document.getElementById('registerCardForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const user_id = document.getElementById('cardUserSelect').value;
    const rfid_uid = document.getElementById('cardUidInput').value.trim();

    const res = await API.request(`/api/users/${user_id}/cards`, {
        method: 'POST',
        body: JSON.stringify({ rfid_uid })
    });

    if (res.ok) {
        alert('Card registered!');
        document.getElementById('registerCardForm').reset();
        loadCards();
    } else {
        const data = await res.json();
        alert(data.error || 'Failed to register card');
    }
});

// Enrolment
async function loadEnrolmentUsers() {
    const users = await API.json('/api/users?page=1&per_page=100');
    const select = document.getElementById('enrolUserSelect');
    select.innerHTML = '<option value="">Select user...</option>';
    users?.users.forEach(u => {
        const opt = document.createElement('option');
        opt.value = u.user_id;
        opt.textContent = `${u.username} (${u.full_name})`;
        select.appendChild(opt);
    });

    const statusDiv = document.getElementById('enrolmentStatus');
    statusDiv.innerHTML = '';
    users?.users.forEach(u => {
        const div = document.createElement('div');
        div.className = 'd-flex justify-content-between align-items-center py-2 border-bottom border-secondary';
        div.innerHTML = `
            <span>${escapeHtml(u.username)}</span>
            <span>${u.has_face_template ? '<i class="bi bi-check-circle-fill text-success"></i> Enrolled' : '<i class="bi bi-x-circle-fill text-muted"></i> Not enrolled'}</span>
        `;
        statusDiv.appendChild(div);
    });
}

const enrolImageInput = document.getElementById('enrolImageInput');
if (enrolImageInput) {
    enrolImageInput.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                const preview = document.getElementById('enrolPreview');
                preview.src = ev.target.result;
                preview.classList.remove('d-none');
            };
            reader.readAsDataURL(file);
        }
    });
}

document.getElementById('enrolFaceForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const user_id = document.getElementById('enrolUserSelect').value;
    const file = document.getElementById('enrolImageInput').files[0];
    const alert = document.getElementById('enrolAlert');

    if (!user_id || !file) return;

    const formData = new FormData();
    formData.append('image', file);

    const res = await fetch(`/api/users/${user_id}/face`, {
        method: 'POST',
        body: formData
    });

    if (res.ok) {
        alert.className = 'alert alert-success';
        alert.textContent = 'Face enrolled successfully!';
    } else {
        const data = await res.json();
        alert.className = 'alert alert-danger';
        alert.textContent = data.error || 'Enrolment failed';
    }
    alert.classList.remove('d-none');
    loadEnrolmentUsers();
});

// Logs
let currentLogsPage = 1;

async function loadLogs(page = 1) {
    currentLogsPage = page;
    const decision = document.getElementById('logFilterDecision')?.value || '';
    const fromDate = document.getElementById('logFilterFrom')?.value || '';
    const toDate = document.getElementById('logFilterTo')?.value || '';

    let url = `/api/logs?page=${page}&per_page=20`;
    if (decision) url += `&decision=${decision}`;
    if (fromDate) url += `&from=${fromDate}`;
    if (toDate) url += `&to=${toDate}`;

    const data = await API.json(url);
    renderLogsTable(data?.logs || [], 'logsTable');
    renderPagination(data, 'logsPagination', loadLogs);
}

function renderLogsTable(logs, tableId) {
    const tbody = document.getElementById(tableId);
    if (!tbody) return;
    tbody.innerHTML = '';
    logs.forEach(log => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td>${formatDate(log.attempt_time)}</td>
            <td>${escapeHtml(log.username || 'Unknown')}</td>
            <td>${boolIcon(log.pin_result)}</td>
            <td>${boolIcon(log.rfid_result)}</td>
            <td>${boolIcon(log.face_result)}</td>
            <td>${log.face_distance !== null ? log.face_distance.toFixed(4) : '-'}</td>
            <td><span class="badge ${log.final_decision === 'granted' ? 'bg-success' : 'bg-danger'}">${log.final_decision}</span></td>
        `;
        tbody.appendChild(tr);
    });
}

document.getElementById('applyLogFilters')?.addEventListener('click', () => loadLogs(1));

// Evaluation
function loadEvaluation() {
    const slider = document.getElementById('thresholdSlider');
    const display = document.getElementById('thresholdValue');
    const display2 = document.getElementById('thresholdDisplay');

    slider?.addEventListener('input', () => {
        display.textContent = parseFloat(slider.value).toFixed(2);
        display2.textContent = parseFloat(slider.value).toFixed(2);
    });
}

// Test Verify
document.getElementById('verifyForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const username = document.getElementById('verifyUsername').value.trim();
    const pin = document.getElementById('verifyPin').value;
    const rfid_uid = document.getElementById('verifyRfid').value.trim();
    const file = document.getElementById('verifyImage').files[0];
    const threshold = parseFloat(document.getElementById('verifyThreshold').value);
    const resultDiv = document.getElementById('verifyResult');

    if (!file) {
        resultDiv.innerHTML = '<div class="alert alert-danger">Please select a face image</div>';
        return;
    }

    const reader = new FileReader();
    reader.onload = async (ev) => {
        const base64 = ev.target.result.split(',')[1];
        const res = await API.request('/api/access/verify', {
            method: 'POST',
            body: JSON.stringify({ username, pin, rfid_uid, face_image: base64, threshold })
        });

        const data = await res.json();
        if (res.ok) {
            const granted = data.decision === 'granted';
            resultDiv.innerHTML = `
                <div class="alert ${granted ? 'alert-success' : 'alert-danger'}">
                    <h4 class="alert-heading">${granted ? 'ACCESS GRANTED' : 'ACCESS DENIED'}</h4>
                    <hr>
                    <table class="table table-dark table-sm mb-0">
                        <tr><td>PIN</td><td>${boolIcon(data.factors.pin)}</td></tr>
                        <tr><td>RFID</td><td>${boolIcon(data.factors.rfid)}</td></tr>
                        <tr><td>Face</td><td>${boolIcon(data.factors.face)}</td></tr>
                        <tr><td>Face Distance</td><td>${data.factors.face_distance !== null ? data.factors.face_distance.toFixed(4) : '-'}</td></tr>
                        <tr><td>Threshold</td><td>${data.threshold_used}</td></tr>
                        <tr><td>Reason</td><td><code>${data.reason}</code></td></tr>
                    </table>
                </div>
            `;
        } else {
            resultDiv.innerHTML = `<div class="alert alert-danger">${data.error || 'Verification failed'}</div>`;
        }
    };
    reader.readAsDataURL(file);
});

// Helpers
function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function boolIcon(val) {
    return val
        ? '<i class="bi bi-check-circle-fill text-success"></i>'
        : '<i class="bi bi-x-circle-fill text-danger"></i>';
}

function formatDate(iso) {
    if (!iso) return '-';
    const d = new Date(iso);
    return d.toLocaleString();
}

function renderPagination(data, containerId, callback) {
    const container = document.getElementById(containerId);
    if (!container || !data) return;

    let html = '<ul class="pagination pagination-sm">';
    for (let i = 1; i <= data.pages; i++) {
        html += `<li class="page-item ${i === data.current_page ? 'active' : ''}">
            <a class="page-link bg-dark text-light border-secondary" href="#" onclick="event.preventDefault(); ${callback.name}(${i})">${i}</a>
        </li>`;
    }
    html += '</ul>';
    container.innerHTML = html;
}

// Init
document.addEventListener('DOMContentLoaded', () => {
    initNavigation();
    loadOverview();
});
"}

